/// polysFor: the baked polygons for an emoji codepoint, or null if that codepoint isn't baked.
pub fn polysFor(cp: u32) ?[]const Poly {
    return switch (cp) {
        0x01F986 => &duck,
        0x01F418 => &elephant,
        0x01F992 => &giraffe,
        0x01F993 => &zebra,
        0x01F98F => &rhino,
        0x01F402 => &bull,
        0x01F404 => &cow,
        0x01F416 => &pig,
        else => null,
    };
}
